 let {groups,home='',away='',onChoose}:{groups:any[];home?:string;away?:string;onChoose:(key:string)=>void}=$props();
 let selected=$state('');const rows=$derived(predictionOverview(groups));
 const leader=$derived([...rows].sort((a,b)=>b.selection.modelProb-a.selection.modelProb||String(a.selection.id).localeCompare(String(b.selection.id)))[0]);
</script>
