 <nav class="prediction-grid" aria-label="Market prediction shortcuts">{#each rows as row(row.key)}{@const s=row.selection}<button class="prediction-tab" class:active={selected===row.key} aria-pressed={selected===row.key} aria-label={`Open ${row.title}: ${s.selection}, Model ${(100*s.modelProb).toFixed(1)} percent`} onclick={()=>{selected=row.key;onChoose(row.key);}}>
